import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Github, 
  Linkedin, 
  Mail, 
  X,
  Award,
  Globe,
  Lock,
  Download,
  FileText,
  Volume2,
  VolumeX,
  Phone,
  Briefcase,
  ExternalLink,
  Video
} from 'lucide-react';

import NeuralBackground from './components/NeuralBackground';
import ChatTerminal from './components/ChatTerminal';
import AdminPanel from './components/AdminPanel';
import LoginModal from './components/LoginModal';
import { 
  getNavConfig, 
  getTitles, 
  PROFILE_IMAGE, 
  AVATAR_IMAGE, 
  AVATAR_FALLBACK, 
  INITIAL_DATA,
  SOCIAL_LINKS
} from './constants';
import { SectionId, PortfolioData, Skill } from './types';

// Typewriter Component for the effect
const TypewriterText = ({ text, delay = 0, className = "" }: { text: string, delay?: number, className?: string }) => {
  const [displayedText, setDisplayedText] = useState("");
  const [showCursor, setShowCursor] = useState(false);

  useEffect(() => {
    setDisplayedText(""); // Reset text on text change
    setShowCursor(false);

    // Start showing cursor when typing begins (after delay)
    const cursorTimeout = setTimeout(() => {
      setShowCursor(true);
    }, delay);

    const startTimeout = setTimeout(() => {
      let index = 0;
      const intervalId = setInterval(() => {
        setDisplayedText((prev) => text.slice(0, index + 1));
        index++;
        if (index >= text.length) {
          clearInterval(intervalId);
        }
      }, 80); 
      return () => clearInterval(intervalId);
    }, delay);

    return () => {
      clearTimeout(startTimeout);
      clearTimeout(cursorTimeout);
    };
  }, [text, delay]);

  return (
    <span className={className}>
      {displayedText}
      {showCursor && <span className="animate-pulse ml-1 inline-block w-1 h-[1em] bg-cyan-500 align-middle"></span>}
    </span>
  );
};

// Voice Visualizer Component - Circular Waves (Ondes)
const VoiceVisualizer = ({ isActive, isSpeaking }: { isActive: boolean, isSpeaking: boolean }) => {
  if (!isActive) return null;

  return (
    <div className="absolute inset-0 flex items-center justify-center pointer-events-none -z-10 overflow-visible">
      {[0, 1, 2].map((i) => (
        <motion.div
          key={i}
          initial={{ opacity: 0, scale: 1 }}
          animate={{ 
            opacity: [0.8, 0],
            scale: [1, 2.2], // Expand significantly outward
            borderWidth: ["2px", "0px"]
          }}
          transition={{ 
            duration: isSpeaking ? 1.5 : 4, // Faster when speaking
            repeat: Infinity,
            delay: i * (isSpeaking ? 0.5 : 1.3),
            ease: "easeOut"
          }}
          className={`absolute inset-0 rounded-full border box-border ${isSpeaking ? 'border-cyan-400' : 'border-cyan-500/30'}`}
        />
      ))}
    </div>
  );
};

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<SectionId | null>(null);
  const [rotation, setRotation] = useState(0);
  const [isHoveringHub, setIsHoveringHub] = useState(false);
  const [lang, setLang] = useState<'en' | 'fr'>('en');
  const [portfolioData, setPortfolioData] = useState<PortfolioData>(INITIAL_DATA);

  // Admin State
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);

  // Sound State
  const [isSoundOn, setIsSoundOn] = useState(false);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [isSpeakingContent, setIsSpeakingContent] = useState(false);
  const synthRef = useRef<SpeechSynthesis | null>(null);

  // Dynamic Content Loading based on State
  const navItems = getNavConfig(lang);
  const titles = getTitles(lang);
  const projects = lang === 'en' ? portfolioData.projects.en : portfolioData.projects.fr;
  const certifications = lang === 'en' ? portfolioData.certifications.en : portfolioData.certifications.fr;
  const experiences = lang === 'en' ? portfolioData.experiences.en : portfolioData.experiences.fr;
  const aboutText = lang === 'en' ? portfolioData.about.en : portfolioData.about.fr;
  const resumeLink = lang === 'en' ? portfolioData.resume.en : portfolioData.resume.fr;

  // Initialize Speech Synthesis and Load Voices
  useEffect(() => {
    if (typeof window !== 'undefined' && window.speechSynthesis) {
      synthRef.current = window.speechSynthesis;

      const loadVoices = () => {
        const availableVoices = window.speechSynthesis.getVoices();
        setVoices(availableVoices);
      };

      // Chrome loads voices asynchronously
      if (window.speechSynthesis.onvoiceschanged !== undefined) {
        window.speechSynthesis.onvoiceschanged = loadVoices;
      }
      loadVoices();
    }
  }, []);

  // Helper to find a female-sounding voice for the language
  const getFemaleVoice = (langCode: string) => {
    const langPrefix = langCode === 'en' ? 'en' : 'fr';
    // Extended keywords for female voices across OS
    const femaleKeywords = [
      'google us english', 
      'zira',              
      'samantha',          
      'victoria',          
      'female', 
      'woman', 
      'audrey', 
      'aurora'
    ];

    const langVoices = voices.filter(v => v.lang.toLowerCase().startsWith(langPrefix));
    const femaleVoice = langVoices.find(v => 
      femaleKeywords.some(keyword => v.name.toLowerCase().includes(keyword))
    );

    return femaleVoice || langVoices[0] || voices[0];
  };

  // Speak Function
  const speak = (text: string, force = false) => {
    if ((!isSoundOn && !force) || !synthRef.current) return;

    synthRef.current.cancel();
    setIsSpeakingContent(false);

    // --- PRONUNCIATION CORRECTION ---
    // Replace the written name with phonetic spelling for the audio engine
    let textToSpeak = text;

    if (lang === 'en') {
      // English voices struggle with 'Ajroud', we approximate it to 'Azh-rood' or 'Ash-rood'
      textToSpeak = textToSpeak
        .replace(/Essia/gi, "Ess-ya") 
        .replace(/Ajroud/gi, "Azh-rood");
    } else {
      // French voices are usually better, but we can ensure stability
      textToSpeak = textToSpeak
         .replace(/Essia/gi, "Essia")
         // Adding an 'e' at the end sometimes helps soft 'd' pronunciation in FR TTS
         .replace(/Ajroud/gi, "Ajroude"); 
    }
    // ---------------------------------

    const utterance = new SpeechSynthesisUtterance(textToSpeak);
    const voice = getFemaleVoice(lang);
    if (voice) utterance.voice = voice;

    utterance.rate = 1; 
    utterance.pitch = 1.1; 

    utterance.onstart = () => setIsSpeakingContent(true);
    utterance.onend = () => setIsSpeakingContent(false);
    utterance.onerror = () => setIsSpeakingContent(false);

    synthRef.current.speak(utterance);
  };

  const stopSpeaking = () => {
    if (synthRef.current) {
      synthRef.current.cancel();
      setIsSpeakingContent(false);
    }
  };

  const readSectionContent = () => {
    let textToRead = "";
    if (activeSection === SectionId.PROJECTS) {
      textToRead = `${navItems.find(n => n.id === activeSection)?.label}. ` + 
                   projects.map(p => `${p.title}. ${p.description}`).join('. ');
    } else if (activeSection === SectionId.EXPERIENCE) {
      textToRead = `${navItems.find(n => n.id === activeSection)?.label}. ` +
                    experiences.map(e => `${e.role} at ${e.company}. ${e.description}`).join('. ');
    } else if (activeSection === SectionId.CERTIFICATIONS) {
       textToRead = `${navItems.find(n => n.id === activeSection)?.label}. ` +
                    certifications.map(c => `${c.name} from ${c.issuer}`).join('. ');
    } else if (activeSection === SectionId.ABOUT) {
      // For About, we read bio and list skills
      const skillNames = portfolioData.skills.map(s => s.name).join(', ');
      textToRead = `${navItems.find(n => n.id === activeSection)?.label}. ${aboutText}. My technical skills include: ${skillNames}`;
    } else if (activeSection === SectionId.HOME) {
      textToRead = lang === 'en' ? "Resume section. You can download my CV here." : "Section CV. Vous pouvez télécharger mon CV ici.";
    }

    if (textToRead) {
      speak(textToRead, true); 
    }
  };

  // Auto-Read Section Content on Open
  useEffect(() => {
    if (activeSection && isSoundOn) {
      stopSpeaking();
      const timeout = setTimeout(() => {
        readSectionContent();
      }, 600);
      return () => clearTimeout(timeout);
    } else if (!activeSection) {
      stopSpeaking();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeSection, isSoundOn, lang]);

  // Welcome Speech
  useEffect(() => {
    if (isSoundOn && !activeSection) {
      const welcomeMsg = lang === 'en' 
        ? "Welcome to my portfolio. I am Essia Ajroud, AI Engineer." 
        : "Bienvenue sur mon portfolio. Je suis Essia Ajroud, ingénieure en intelligence artificielle.";
      speak(welcomeMsg);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isSoundOn, lang, activeSection]);

  // Auto-rotation
  useEffect(() => {
    if (activeSection !== null || isHoveringHub) return;
    const interval = setInterval(() => {
      setRotation((prev) => (prev + 0.15) % 360);
    }, 50);
    return () => clearInterval(interval);
  }, [activeSection, isHoveringHub]);

  const handleNavClick = (id: SectionId) => {
    setActiveSection(activeSection === id ? null : id);
  };

  const toggleLanguage = () => {
    stopSpeaking();
    setLang(prev => prev === 'en' ? 'fr' : 'en');
  };

  // Helper to group skills by category
  const groupedSkills = portfolioData.skills.reduce((acc, skill) => {
    if (!acc[skill.category]) acc[skill.category] = [];
    acc[skill.category].push(skill);
    return acc;
  }, {} as Record<string, Skill[]>);

  // Orbital Radius
  const radius = 140;

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center overflow-hidden bg-slate-950 text-slate-200">
      <NeuralBackground />

      {/* Login Modal */}
      {showLoginModal && (
        <LoginModal 
          onLogin={() => {
            setShowLoginModal(false);
            setIsAdminOpen(true);
          }}
          onClose={() => setShowLoginModal(false)}
        />
      )}

      {/* Admin Panel Modal */}
      {isAdminOpen && (
        <AdminPanel 
          data={portfolioData}
          onUpdate={(newData) => {
            setPortfolioData(newData);
            setIsAdminOpen(false);
          }}
          onClose={() => setIsAdminOpen(false)}
        />
      )}

      {/* Top Bar Controls */}
      <div className="fixed top-6 left-6 z-50 flex gap-4">
         <button 
           onClick={() => setShowLoginModal(true)}
           className="p-2 bg-slate-900/80 border border-slate-700 hover:border-cyan-500/50 rounded-full text-slate-500 hover:text-cyan-400 transition-colors"
           title="Admin Login"
         >
           <Lock size={14} />
         </button>
      </div>

      <div className="fixed top-6 right-6 z-50 flex gap-3">
        {/* Language Toggle */}
        <button 
          onClick={toggleLanguage}
          className="flex items-center gap-2 px-4 py-2 bg-slate-900/80 border border-cyan-500/30 rounded-full backdrop-blur-md text-cyan-400 hover:bg-cyan-500/10 transition-all font-mono text-xs"
        >
          <Globe size={14} />
          <span className={lang === 'en' ? 'font-bold' : 'opacity-50'}>EN</span>
          <span className="opacity-30">|</span>
          <span className={lang === 'fr' ? 'font-bold' : 'opacity-50'}>FR</span>
        </button>
      </div>

      {/* Sound Toggle - Bottom Right */}
      <div className="fixed bottom-6 right-6 z-50">
          <button
            onClick={() => {
              const newState = !isSoundOn;
              setIsSoundOn(newState);
              if (!newState) stopSpeaking();
            }}
            className={`relative z-10 p-3 rounded-full border shadow-lg transition-all ${
              isSoundOn 
                ? 'bg-cyan-900/50 border-cyan-500/50 text-cyan-400 shadow-[0_0_15px_rgba(6,182,212,0.3)]' 
                : 'bg-slate-900/80 border-slate-700 text-slate-500'
            }`}
            title={isSoundOn ? (lang === 'en' ? "Turn Sound Off" : "Désactiver le son") : (lang === 'en' ? "Turn Sound On" : "Activer le son")}
          >
            {isSoundOn ? <Volume2 size={20} /> : <VolumeX size={20} />}
          </button>
      </div>

      {/* Central Hub Container */}
      <div className="relative w-full h-full flex flex-col items-center justify-center z-10 p-4">

        {/* Title Header (Only visible when Home) */}
        <AnimatePresence>
          {!activeSection && (
            <motion.div 
              initial={{ opacity: 0, y: -50 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.3 } }}
              className="z-20 text-center mb-8 md:mb-12 flex flex-col items-center"
            >
              {/* Typewriter Title */}
              <h1 className="text-3xl md:text-5xl font-bold text-white tracking-tighter mb-4 h-16 flex flex-col md:flex-row items-center justify-center gap-2">
                <TypewriterText text={titles.welcome} className="whitespace-pre" />
                <span className="text-cyan-500">
                  <TypewriterText text={` ${titles.portfolio}`} delay={1500} />
                </span>
              </h1>

              <div className="flex flex-col md:flex-row items-center justify-center gap-2 md:gap-4 text-slate-300 font-mono text-xs md:text-sm tracking-wide">
                <span className="text-cyan-400 font-bold">ESSIA AJROUD</span>
                <span className="hidden md:inline text-slate-600">|</span>
                <span>{titles.role}</span>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Neural Hub / Navigation System */}
        <div 
          className={`relative transition-all duration-700 ease-in-out ${
            activeSection ? 'scale-75 md:translate-x-[-30vw]' : 'scale-100'
          }`}
          style={{ width: '400px', height: '400px' }}
          onMouseEnter={() => setIsHoveringHub(true)}
          onMouseLeave={() => setIsHoveringHub(false)}
        >
          {/* Orbital Rings */}
          <div className="absolute inset-0 rounded-full border border-cyan-500/10 animate-[spin_10s_linear_infinite]"></div>
          <div className="absolute inset-4 rounded-full border border-cyan-500/20 animate-[spin_15s_linear_infinite_reverse]"></div>

          {/* Central Core (Profile) */}
          <div 
            className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-32 h-32 md:w-40 md:h-40 z-20 group cursor-pointer"
            onMouseEnter={() => {
              if (!isSpeakingContent) {
                const msg = lang === 'en' ? "That is me, Essia." : "C'est moi, Essia.";
                speak(msg);
              }
            }}
          >
             {/* Visualizer Effect (Behind Profile) */}
             <VoiceVisualizer isActive={isSoundOn} isSpeaking={isSpeakingContent} />

             <div className="relative w-full h-full">
                {/* Glow Effect */}
                <div className="absolute inset-0 bg-cyan-500/20 rounded-full blur-xl group-hover:bg-cyan-500/40 transition-all duration-500"></div>
                <div className="relative w-full h-full rounded-full overflow-hidden border-2 border-cyan-500/50 bg-slate-900 flex items-center justify-center">
                    <img src={PROFILE_IMAGE} alt="Essia Ajroud" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                </div>
             </div>
          </div>

          {/* Nav Items (Planets) */}
          {navItems.map((item) => {
            // Calculate Position
            const angleRad = ((item.angle + rotation) * Math.PI) / 180;
            const x = Math.cos(angleRad) * radius;
            const y = Math.sin(angleRad) * radius;

            const isActive = activeSection === item.id;

            return (
              <motion.button
                key={item.id}
                className={`absolute w-14 h-14 rounded-full flex items-center justify-center border transition-colors duration-300 z-30
                  ${isActive 
                    ? 'bg-cyan-500 text-black border-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.6)]' 
                    : 'bg-slate-900/80 text-cyan-400 border-cyan-500/30 hover:border-cyan-400 hover:bg-slate-800'
                  }`}
                style={{
                  top: `calc(50% + ${y}px)`,
                  left: `calc(50% + ${x}px)`,
                }}
                initial={{ x: "-50%", y: "-50%" }}
                animate={{ x: "-50%", y: "-50%" }}
                whileHover={{ scale: 1.2, x: "-50%", y: "-50%" }}
                onClick={() => handleNavClick(item.id)}
                onMouseEnter={() => {
                  setIsHoveringHub(true);
                  if (!activeSection) {
                    speak(item.label);
                  }
                }}
                onMouseLeave={() => setIsHoveringHub(false)}
                title={item.label}
              >
                <item.icon size={22} />
                <span className="absolute -bottom-8 text-xs font-mono whitespace-nowrap bg-black/50 px-2 py-1 rounded text-cyan-300 opacity-0 hover:opacity-100 transition-opacity pointer-events-none z-40">
                  {item.label}
                </span>
              </motion.button>
            );
          })}
        </div>

        {/* Content Overlay / Modal */}
        <AnimatePresence mode="wait">
          {activeSection && (
            <motion.div
              key={activeSection}
              initial={{ opacity: 0, x: 50, filter: 'blur(10px)' }}
              animate={{ opacity: 1, x: 0, filter: 'blur(0px)' }}
              exit={{ opacity: 0, x: 50, filter: 'blur(10px)' }}
              transition={{ duration: 0.5, ease: "circOut" }}
              className="absolute inset-0 md:inset-auto md:right-10 md:w-[50vw] md:h-[80vh] bg-slate-900/90 backdrop-blur-md md:rounded-2xl border border-cyan-500/20 shadow-2xl overflow-hidden z-40 flex flex-col"
            >
              {/* Modal Header */}
              <div className="flex items-center justify-between p-6 border-b border-cyan-500/20 z-20 bg-slate-900/80">
                <div className="flex items-center gap-3">
                  <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                    {navItems.find(n => n.id === activeSection)?.label.toUpperCase()}
                  </h2>
                </div>

                <button 
                  onClick={() => {
                    setActiveSection(null);
                    stopSpeaking();
                  }}
                  className="p-2 hover:bg-white/10 rounded-full transition-colors text-slate-400 hover:text-white"
                >
                  <X size={24} />
                </button>
              </div>

              {/* Modal Content */}
              <div className="flex-1 overflow-y-auto p-6 scrollbar-thin relative z-10">

                {activeSection === SectionId.PROJECTS && (
                  <div className="grid grid-cols-1 gap-6">
                    {projects.map(project => (
                      <div key={project.id} className="group bg-slate-950/50 p-6 rounded-xl border border-slate-800 hover:border-cyan-500/50 transition-all duration-300">
                        <div className="flex justify-between items-start mb-2">
                          <h3 className="text-xl font-bold text-cyan-100 group-hover:text-cyan-400 transition-colors">{project.title}</h3>
                          <span className="text-xs font-mono px-2 py-1 bg-cyan-900/30 text-cyan-300 rounded border border-cyan-500/20">{project.category}</span>
                        </div>
                        <p className="text-slate-400 mb-4 text-sm leading-relaxed">{project.description}</p>

                        <div className="flex flex-wrap gap-2 mb-4">
                          {project.techStack.map(tech => (
                            <span key={tech} className="text-xs text-slate-500 border border-slate-700 px-2 py-0.5 rounded-full">
                              {tech}
                            </span>
                          ))}
                        </div>

                        {/* NEW: Project Links (Conditional) */}
                        {(project.githubUrl || project.demoUrl) && (
                           <div className="flex gap-3 pt-4 border-t border-slate-800/50">
                              {project.githubUrl && (
                                <a href={project.githubUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-xs text-cyan-500 hover:text-cyan-300 hover:underline">
                                  <Github size={14} /> Code
                                </a>
                              )}
                              {project.demoUrl && (
                                <a href={project.demoUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-xs text-cyan-500 hover:text-cyan-300 hover:underline">
                                  <Video size={14} /> Demo
                                </a>
                              )}
                           </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {activeSection === SectionId.EXPERIENCE && (
                  <div className="relative border-l border-cyan-900/50 ml-3 space-y-8 py-2">
                    {experiences.map((exp) => (
                      <div key={exp.id} className="relative pl-8">
                         {/* Timeline Dot */}
                         <div className="absolute -left-1.5 top-1.5 w-3 h-3 rounded-full bg-slate-900 border border-cyan-500"></div>

                         <div className="bg-slate-950/50 p-5 rounded-lg border border-slate-800 hover:border-cyan-500/30 transition-all">
                            <h3 className="text-lg font-bold text-white">{exp.role}</h3>
                            <div className="flex justify-between items-center text-sm mb-3">
                               <span className="text-cyan-400">{exp.company}</span>
                               <span className="text-slate-500 font-mono text-xs">{exp.period}</span>
                            </div>
                            <p className="text-slate-400 text-sm leading-relaxed">
                               {exp.description}
                            </p>
                         </div>
                      </div>
                    ))}
                  </div>
                )}

                {activeSection === SectionId.CERTIFICATIONS && (
                  <div className="grid grid-cols-1 gap-4">
                     {certifications.map(cert => (
                       <div key={cert.id} className="flex items-center gap-4 bg-slate-950/50 p-4 rounded-lg border border-slate-800 hover:border-cyan-500/50 transition-all">
                          <div className="p-3 bg-cyan-900/20 rounded-full text-cyan-400">
                             <Award size={24} />
                          </div>
                          <div>
                             <h3 className="text-lg font-bold text-white">{cert.name}</h3>
                             <p className="text-sm text-cyan-500">{cert.issuer}</p>
                             <p className="text-xs text-slate-500 mt-1">{cert.date}</p>
                          </div>
                       </div>
                     ))}
                  </div>
                )}

                {activeSection === SectionId.ABOUT && (
                   <div className="relative h-full flex flex-col">
                      {/* Avatar Background */}
                      <motion.div 
                        className="absolute inset-0 flex items-center justify-center pointer-events-none z-0"
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ 
                          opacity: 1, 
                          scale: 1,
                          y: [0, -20, 0], // Floating up and down
                          rotate: [-2, 2, -2] // Gentle Sway
                        }}
                        transition={{ 
                          opacity: { duration: 0.5 },
                          scale: { duration: 0.5 },
                          y: { 
                            duration: 4, 
                            repeat: Infinity, 
                            ease: "easeInOut" 
                          },
                          rotate: {
                             duration: 6,
                             repeat: Infinity,
                             ease: "easeInOut"
                          }
                        }}
                      >
                          <img 
                            src={AVATAR_IMAGE}
                            onError={(e) => {
                                // Fallback if image not found
                                e.currentTarget.src = AVATAR_FALLBACK;
                            }}
                            alt="Graduate Avatar"
                            className="w-[85%] h-[85%] object-contain opacity-50 drop-shadow-[0_0_30px_rgba(6,182,212,0.4)]"
                          />
                      </motion.div>

                      {/* Content */}
                      <div className="relative z-10 space-y-6">
                        <div className="flex items-start gap-4 p-6 bg-slate-950/80 border border-cyan-500/30 rounded-lg shadow-lg backdrop-blur-sm">
                          <p className="text-slate-200 leading-relaxed font-mono text-sm whitespace-pre-wrap">
                            {aboutText}
                          </p>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="bg-slate-950/90 backdrop-blur-sm p-4 rounded-lg border border-slate-800 hover:border-cyan-500/30 transition-colors">
                            <h4 className="text-cyan-400 font-bold mb-2 flex items-center gap-2">
                               <span className="w-2 h-2 bg-cyan-500 rounded-full"></span> {titles.education}
                            </h4>
                            <ul className="space-y-2 text-sm text-slate-300">
                              <li className="flex gap-2"><span className="text-cyan-500/50">›</span> M.Sc Data Science & AI</li>
                              <li className="flex gap-2"><span className="text-cyan-500/50">›</span> B.Sc Computer Engineering</li>
                            </ul>
                          </div>
                          <div className="bg-slate-950/90 backdrop-blur-sm p-4 rounded-lg border border-slate-800 hover:border-cyan-500/30 transition-colors">
                             <h4 className="text-cyan-400 font-bold mb-4 flex items-center gap-2">
                                <span className="w-2 h-2 bg-cyan-500 rounded-full"></span> {titles.skills}
                             </h4>
                             <div className="space-y-4 max-h-[300px] overflow-y-auto pr-2 scrollbar-thin">
                                {Object.entries(groupedSkills).map(([category, skills]) => (
                                  <div key={category} className="mb-4 last:mb-0">
                                     <h5 className="text-[10px] uppercase font-bold text-slate-500 mb-2">{category}</h5>
                                     <div className="flex flex-wrap gap-2">
                                       {(skills as Skill[]).map((skill, idx) => (
                                         <span 
                                            key={idx}
                                            className="px-2 py-1 bg-slate-900 border border-slate-700 rounded text-xs text-cyan-300 hover:border-cyan-500/50 hover:bg-cyan-900/10 transition-colors cursor-default"
                                          >
                                            {skill.name}
                                         </span>
                                       ))}
                                     </div>
                                  </div>
                                ))}
                             </div>
                          </div>
                        </div>
                      </div>
                   </div>
                )}

                {activeSection === SectionId.CHAT && (
                  <div className="h-full flex flex-col">
                    <p className="text-sm text-slate-400 mb-4 text-center">
                      {titles.interact}
                    </p>
                    <ChatTerminal />
                  </div>
                )}

                {activeSection === SectionId.CONTACT && (
                  <div className="flex flex-col items-center justify-center h-full space-y-8">
                    <div className="text-center">
                       <h3 className="text-2xl font-bold text-white mb-2">{titles.connect}</h3>
                       <p className="text-slate-400">{titles.collab}</p>
                    </div>

                    <div className="grid grid-cols-2 gap-6 md:flex md:gap-8">
                      <a href={SOCIAL_LINKS.linkedin} target="_blank" rel="noopener noreferrer" className="p-4 bg-slate-800 rounded-full hover:bg-cyan-600 hover:text-white transition-all text-slate-300 flex items-center justify-center">
                        <Linkedin size={28} />
                      </a>
                      <a href={SOCIAL_LINKS.github} target="_blank" rel="noopener noreferrer" className="p-4 bg-slate-800 rounded-full hover:bg-slate-100 hover:text-black transition-all text-slate-300 flex items-center justify-center">
                        <Github size={28} />
                      </a>
                      <a href={`mailto:${SOCIAL_LINKS.email}`} className="p-4 bg-slate-800 rounded-full hover:bg-cyan-600 hover:text-white transition-all text-slate-300 flex items-center justify-center">
                        <Mail size={28} />
                      </a>
                      <a href={`tel:${SOCIAL_LINKS.phone}`} className="p-4 bg-slate-800 rounded-full hover:bg-green-600 hover:text-white transition-all text-slate-300 flex items-center justify-center" title={SOCIAL_LINKS.phone}>
                        <Phone size={28} />
                      </a>
                    </div>
                    <div className="text-slate-500 font-mono text-sm">
                      {SOCIAL_LINKS.phone}
                    </div>
                  </div>
                )}

                {/* RESUME SECTION (Formerly HOME) */}
                {activeSection === SectionId.HOME && (
                  <div className="h-full flex flex-col items-center justify-center text-center space-y-8">
                     <div className="p-8 bg-slate-950/50 border border-cyan-500/30 rounded-2xl max-w-sm w-full relative group">
                        <div className="absolute inset-0 bg-cyan-500/5 blur-xl group-hover:bg-cyan-500/10 transition-all"></div>
                        <FileText size={48} className="mx-auto text-cyan-400 mb-4" />
                        <h3 className="text-2xl font-bold text-white mb-2">{titles.download}</h3>
                        <p className="text-slate-400 text-sm mb-6">
                          {lang === 'en' 
                            ? "Get a detailed PDF version of my resume including extensive project history and academic details." 
                            : "Obtenez une version PDF détaillée de mon CV incluant l'historique complet des projets et les détails académiques."}
                        </p>

                        <a 
                          href={resumeLink} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="flex items-center justify-center gap-2 w-full py-3 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg shadow-lg shadow-cyan-500/20 transition-all font-bold uppercase tracking-wide text-sm"
                        >
                          <Download size={18} />
                          {titles.download}
                        </a>
                        <div className="mt-4 text-[10px] text-slate-500 font-mono">
                           FILE: {lang === 'en' ? 'CV_ESSIA_EN.pdf' : 'CV_ESSIA_FR.pdf'}
                        </div>
                     </div>
                  </div>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Footer / Status Bar */}
      <div className="fixed bottom-0 left-0 w-full p-2 bg-slate-950/80 backdrop-blur border-t border-slate-800 flex justify-center items-center gap-6 text-[10px] md:text-xs font-mono text-slate-500 z-50">
         <a href={SOCIAL_LINKS.github} target="_blank" rel="noopener noreferrer" className="hover:text-cyan-400 transition-colors flex items-center gap-2">
            <Github size={14} />
            <span className="hidden md:inline">GitHub</span>
         </a>
         <a href={SOCIAL_LINKS.linkedin} target="_blank" rel="noopener noreferrer" className="hover:text-cyan-400 transition-colors flex items-center gap-2">
            <Linkedin size={14} />
            <span className="hidden md:inline">LinkedIn</span>
         </a>
         <a href={`mailto:${SOCIAL_LINKS.email}`} className="hover:text-cyan-400 transition-colors flex items-center gap-2">
            <Mail size={14} />
            <span>{SOCIAL_LINKS.email}</span>
         </a>
      </div>
    </div>
  );
};

export default App;
